/* Standalone SDL/EGL fbdev swap timing. No game code, no display timing writes. */
#define _POSIX_C_SOURCE 200809L
#include <SDL2/SDL.h>
#include <GLES2/gl2.h>
#include <EGL/egl.h>
#include <linux/fb.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>
#include <stdio.h>
#include <time.h>
#include <errno.h>
#include <signal.h>
static double now(void){struct timespec t;clock_gettime(CLOCK_MONOTONIC_RAW,&t);return t.tv_sec+t.tv_nsec*1e-9;}
int main(void){enum{N=3001};static double begin[N],end[N];puts("# clock=CLOCK_MONOTONIC_RAW; all samples retained");if(SDL_Init(SDL_INIT_VIDEO))return 2;SDL_GL_SetAttribute(SDL_GL_CONTEXT_PROFILE_MASK,SDL_GL_CONTEXT_PROFILE_ES);SDL_GL_SetAttribute(SDL_GL_CONTEXT_MAJOR_VERSION,2);SDL_GL_SetAttribute(SDL_GL_CONTEXT_MINOR_VERSION,0);SDL_GL_SetAttribute(SDL_GL_DOUBLEBUFFER,1);SDL_GL_SetAttribute(SDL_GL_DEPTH_SIZE,16);SDL_GL_SetAttribute(SDL_GL_RED_SIZE,8);SDL_GL_SetAttribute(SDL_GL_GREEN_SIZE,8);SDL_GL_SetAttribute(SDL_GL_BLUE_SIZE,8);SDL_Window*w=SDL_CreateWindow("Stage1b panel timing",0,0,640,480,SDL_WINDOW_OPENGL|SDL_WINDOW_FULLSCREEN);if(!w){fprintf(stderr,"%s\n",SDL_GetError());return 2;}SDL_GLContext c=SDL_GL_CreateContext(w);if(!c){fprintf(stderr,"%s\n",SDL_GetError());return 2;}if(SDL_GL_MakeCurrent(w,c))return 2;int width,height;SDL_GL_GetDrawableSize(w,&width,&height);GLint depth;glGetIntegerv(GL_DEPTH_BITS,&depth);printf("# drawable=%dx%d depth=%d\n",width,height,depth);if(width!=640||height!=480||depth<16)return 2;EGLDisplay ed=eglGetCurrentDisplay();EGLint id,nconfigs;EGLConfig configs[64];if(eglQueryContext(ed,eglGetCurrentContext(),EGL_CONFIG_ID,&id)&&eglGetConfigs(ed,configs,64,&nconfigs)){for(int k=0;k<nconfigs;k++){EGLint other;if(eglGetConfigAttrib(ed,configs[k],EGL_CONFIG_ID,&other)&&id==other){EGLint low=-1,high=-1;eglGetConfigAttrib(ed,configs[k],EGL_MIN_SWAP_INTERVAL,&low);eglGetConfigAttrib(ed,configs[k],EGL_MAX_SWAP_INTERVAL,&high);printf("# egl_config=%d min_swap_interval=%d max_swap_interval=%d\n",id,low,high);}}}int rc=SDL_GL_SetSwapInterval(1);printf("# swap_interval_set_rc=%d reported=%d driver=%s error=%s\n",rc,SDL_GL_GetSwapInterval(),SDL_GetCurrentVideoDriver(),SDL_GetError());SDL_DisplayMode m;if(!SDL_GetCurrentDisplayMode(0,&m))printf("# sdl_mode=%dx%d refresh_rate=%d\n",m.w,m.h,m.refresh_rate);printf("# gl=%s renderer=%s\n",glGetString(GL_VERSION),glGetString(GL_RENDERER));int fd=open("/dev/fb0",O_RDONLY);struct fb_var_screeninfo v;if(fd>=0&&!ioctl(fd,FBIOGET_VSCREENINFO,&v))printf("# fb xres=%u yres=%u virtual=%ux%u pixclock_ps=%u left=%u right=%u upper=%u lower=%u hsync=%u vsync=%u vmode=%u\n",v.xres,v.yres,v.xres_virtual,v.yres_virtual,v.pixclock,v.left_margin,v.right_margin,v.upper_margin,v.lower_margin,v.hsync_len,v.vsync_len,v.vmode);if(fd>=0)close(fd);for(int i=0;i<N;i++){glClearColor(i&1?1:0,0,i&1?0:1,1);glClear(GL_COLOR_BUFFER_BIT);begin[i]=now();SDL_GL_SwapWindow(w);end[i]=now();}puts("swap,begin_seconds,return_seconds,blocked_ms,interval_ms");for(int i=0;i<N;i++)printf("%d,%.9f,%.9f,%.9f,%.9f\n",i,begin[i],end[i],(end[i]-begin[i])*1000,i?(end[i]-end[i-1])*1000:0);fflush(stdout);{int fd2=open("/dev/fb0",O_RDONLY);unsigned arg=0;static double vb[N];int count=0,err=0;if(fd2>=0){for(int i=0;i<N;i++){alarm(2);int r=ioctl(fd2,FBIO_WAITFORVSYNC,&arg);alarm(0);if(r){err=errno;break;}vb[count++]=now();}close(fd2);}else err=errno;printf("# fb_waitforvsync count=%d errno=%d\n",count,err);for(int i=0;i<count;i++)printf("# VSYNC %d %.9f %.9f\n",i,vb[i],i?(vb[i]-vb[i-1])*1000:0);}SDL_GL_DeleteContext(c);SDL_DestroyWindow(w);SDL_Quit();return 0;}
